import numpy as np

def solve_z2(n):
    # Variables: a_{i,j} for 0 <= i < n-1, 0 <= j < n-1 ( (n-1)^2 variables )
    # b_i for 0 <= i < n ( n variables )
    # c_j for 0 <= j < n ( n variables )
    # Total variables: (n-1)^2 + 2n

    num_a = (n - 1)**2
    num_b = n
    num_c = n
    num_vars = num_a + num_b + num_c
    num_eqs = n * n

    matrix = np.zeros((num_eqs, num_vars), dtype=int)

    # Map variables to indices
    def get_a(i, j):
        if 0 <= i < n - 1 and 0 <= j < n - 1:
            return i * (n - 1) + j
        return -1

    def get_b(i):
        return num_a + i

    def get_c(j):
        return num_a + num_b + j

    for i in range(n):
        for j in range(n):
            # Equation for cell (i, j): a_{i,j} + a_{i-1,j} + a_{i,j-1} + b_i + c_j = 0
            row = i * n + j

            # a_{i,j}
            idx = get_a(i, j)
            if idx != -1:
                matrix[row, idx] = 1

            # a_{i-1,j}
            idx = get_a(i - 1, j)
            if idx != -1:
                matrix[row, idx] = 1

            # a_{i,j-1}
            idx = get_a(i, j - 1)
            if idx != -1:
                matrix[row, idx] = 1

            # b_i
            matrix[row, get_b(i)] = 1

            # c_j
            matrix[row, get_c(j)] = 1

    # We want to find if there is a solution with at least one a_{i,j} = 1
    # The system is Ax = 0.
    # We can use Gaussian elimination over GF(2).

    # Convert to GF(2) matrix
    from sympy import Matrix
    M = Matrix(matrix)
    null_space = M.nullspace()

    if not null_space:
        return False

    # Check if any vector in the null space has at least one 'a' component != 0
    for vec in null_space:
        for k in range(num_a):
            if vec[k] != 0:
                return True
    return False

for n in range(2, 7):
    print(f"n={n}: {solve_z2(n)}")

