def solve_gf2(n):
    num_a = (n - 1)**2
    num_b = n
    num_c = n
    num_vars = num_a + num_b + num_c
    num_eqs = n * n

    matrix = []
    def get_a(i, j):
        if 0 <= i < n - 1 and 0 <= j < n - 1:
            return i * (n - 1) + j
        return -1

    for i in range(n):
        for j in range(n):
            row = [0] * num_vars
            idx = get_a(i, j)
            if idx != -1: row[idx] = 1
            idx = get_a(i - 1, j)
            if idx != -1: row[idx] = 1
            idx = get_a(i, j - 1)
            if idx != -1: row[idx] = 1
            row[num_a + i] = 1
            row[num_a + num_b + j] = 1
            matrix.append(row)

    rows = len(matrix)
    cols = len(matrix[0])
    pivot_row = 0
    pivot_cols = []
    for j in range(cols):
        if pivot_row < rows:
            found = False
            for i in range(pivot_row, rows):
                if matrix[i][j] == 1:
                    matrix[pivot_row], matrix[i] = matrix[i], matrix[pivot_row]
                    found = True
                    break
            if not found:
                continue

            pivot_cols.append(j)
            for i in range(rows):
                if i != pivot_row and matrix[i][j] == 1:
                    for k in range(j, cols):
                        matrix[i][k] ^= matrix[pivot_row][k]
            pivot_row += 1

    is_pivot = [False] * cols
    for c in pivot_cols:
        is_pivot[c] = True

    for j in range(cols):
        if not is_pivot[j]:
            vec = [0] * cols
            vec[j] = 1
            for r in range(len(pivot_cols)):
                if matrix[r][j] == 1:
                    vec[pivot_cols[r]] = 1
            for k in range(num_a):
                if vec[k] == 1:
                    return True
    return False

